# Construct 28x28 output with separator grid at indices 4,9,14,19,24; 5x5 cells, each 4x4.
N=28
out=[[0]*N for _ in range(N)]
for r in range(N):
    for c in range(N):
        if r in [4,9,14,19,24] or c in [4,9,14,19,24]: out[r][c]=8
# cell-level colors: vertical 3 in cell col2; row1 horizontal 2 except crossing; col0 vertical 2 rows1-3
for br in range(5):
  for bc in range(5):
    color=0
    if bc==2: color=3
    if br==1: color=2
    if bc==0 and br in (1,2,3): color=2
    if br==1 and bc==2: color=6
    for dr in range(4):
      for dc in range(4):
        out[br*5+dr][bc*5+dc]=color
print(__import__('json').dumps(out,separators=(',',':')))

